import{_ as t,a as i,b as o}from"./chunks/di-injector-tree-providers.BelAB5Rx.js";import{_ as r,o as a,c as n,aj as s}from"./chunks/framework.C6uXqnaX.js";const m=JSON.parse('{"title":"Inspect your injectors","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tools/devtools/injectors.md","filePath":"tools/devtools/injectors.md"}'),h={name:"tools/devtools/injectors.md"};function c(l,e,p,d,u,j){return a(),n("div",null,e[0]||(e[0]=[s('<h1 id="inspect-your-injectors" tabindex="-1">Inspect your injectors <a class="header-anchor" href="#inspect-your-injectors" aria-label="Permalink to &quot;Inspect your injectors&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>The Injector Tree is available for Angular Applications built with version 17 or higher.</p></div><h2 id="view-the-injector-hierarchy-of-your-application" tabindex="-1">View the injector hierarchy of your application <a class="header-anchor" href="#view-the-injector-hierarchy-of-your-application" aria-label="Permalink to &quot;View the injector hierarchy of your application&quot;">​</a></h2><p>The <strong>Injector Tree</strong> tab lets you explore the structure of the Injectors configured in your application. Here you will see two trees representing the <a href="/guide/di/hierarchical-dependency-injection">injector hierarchy</a> of your application. One tree is your environment hierarchy, the other is your element hierarchy.</p><img src="'+t+'" alt="A screenshot of the &#39;Profiler&#39; tab displaying the injector tree tab in Angular Devtools visualizing the injector graph for an example application."><h2 id="visualize-resolution-paths" tabindex="-1">Visualize resolution paths <a class="header-anchor" href="#visualize-resolution-paths" aria-label="Permalink to &quot;Visualize resolution paths&quot;">​</a></h2><p>When a specific injector is selected, the path that Angular&#39;s dependency injection algorithm traverses from that injector to the root is highlighted. For element injectors, this includes highlighting the environment injectors that the dependency injection algorithm jumps to when a dependency cannot be resolved in the element hierarchy.</p><p>See <a href="/guide/di/hierarchical-dependency-injection#resolution-rules">resolution rules</a> for more details about how Angular resolves resolution paths.</p><img src="'+i+'" alt="A screenshot of the &#39;Profiler&#39; tab displaying how the injector tree visualize highlights resolution paths when an injector is selected."><h2 id="view-injector-providers" tabindex="-1">View injector providers <a class="header-anchor" href="#view-injector-providers" aria-label="Permalink to &quot;View injector providers&quot;">​</a></h2><p>Clicking an injector that has configured providers will display those providers in a list on the right of the injector tree view. Here you can view the provided token and it&#39;s type. The button on the right of each provider allows you to log the provider in the console.</p><img src="'+o+'" alt="A screenshot of the &#39;Profiler&#39; tab displaying how providers are made visible when an injector is selected.">',12)]))}const y=r(h,[["render",c]]);export{m as __pageData,y as default};
